<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<?php if ( ! avela_elementor_region( 'footer' ) ) : ?>
<footer class="avela-footer"><div class="avela-shell avela-footer-top"><div class="avela-footer-intro"><a class="avela-footer-brand" href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php echo esc_html( get_bloginfo( 'name' ) ); ?>.</a><p><?php echo esc_html( get_theme_mod( 'avela_footer_text', __( 'A considered collection for your everyday rituals.', 'avela' ) ) ); ?></p><div class="avela-socials"><?php foreach ( array( 'instagram' => 'Instagram', 'facebook' => 'Facebook' ) as $key => $label ) { $url = get_theme_mod( 'avela_' . $key ); if ( $url ) { echo '<a href="' . esc_url( $url ) . '">' . esc_html( $label ) . '</a> '; } } ?></div></div>
<div><h2><?php esc_html_e( 'Explore', 'avela' ); ?></h2><?php if ( has_nav_menu( 'footer' ) ) { wp_nav_menu( array( 'theme_location' => 'footer', 'container' => false, 'menu_class' => 'avela-footer-menu', 'depth' => 1 ) ); } else { avela_primary_fallback(); } ?></div>
<div><h2><?php esc_html_e( 'Get in touch', 'avela' ); ?></h2><?php $email = sanitize_email( get_theme_mod( 'avela_contact_email' ) ); $phone = get_theme_mod( 'avela_contact_phone' ); if ( $email ) { echo '<p><a href="' . esc_url( 'mailto:' . $email ) . '">' . esc_html( $email ) . '</a></p>'; } if ( $phone ) { echo '<p><a href="' . esc_url( 'tel:' . preg_replace( '/[^0-9+]/', '', $phone ) ) . '">' . esc_html( $phone ) . '</a></p>'; } ?><p><?php echo nl2br( esc_html( get_theme_mod( 'avela_contact_address', '' ) ) ); ?></p><?php if ( ! $email && ! $phone ) : ?><p><a href="<?php echo esc_url( avela_page_url( 'contact' ) ); ?>"><?php esc_html_e( 'Visit our contact page', 'avela' ); ?></a></p><?php endif; ?></div></div>
<div class="avela-shell avela-footer-bottom"><p>© <?php echo esc_html( wp_date( 'Y' ) ); ?> <?php echo esc_html( get_bloginfo( 'name' ) ); ?></p><div class="avela-policy-links"><?php foreach ( array( 'privacy-policy', 'terms-and-conditions', 'shipping-and-returns' ) as $slug ) { $page = get_page_by_path( $slug ); if ( $page && 'publish' === $page->post_status ) { echo '<a href="' . esc_url( get_permalink( $page ) ) . '">' . esc_html( get_the_title( $page ) ) . '</a> '; } } ?></div></div></footer>
<?php endif; wp_footer(); ?></body></html>
